static void uiFontInit(void)
{
    if (!intraFontInit()) return;
    uiFont = intraFontLoad("flash0:/font/ltn0.pgf", INTRAFONT_CACHE_ASCII);
    if (uiFont) intraFontSetEncoding(uiFont, INTRAFONT_STRING_ASCII);
}

static void uiFontTerm(void)
{
    if (uiFont) { intraFontUnload(uiFont); uiFont = NULL; }
    intraFontShutdown();
}

static void uiText(int x, int baseline, const char *text, u32 color, float size)
{
    if (!uiFont || !text) return;
    sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD, GU_SRC_ALPHA, GU_ONE_MINUS_SRC_ALPHA, 0, 0);
    intraFontSetStyle(uiFont, size, color, 0, 0);
    intraFontPrint(uiFont, (float)x, (float)baseline, text);
    sceGuDisable(GU_TEXTURE_2D);
}

static void drawText(int x,int y,const char *text,u32 color){ uiText(x,y+17,text,color,0.68f); }
static void drawTextSmall(int x,int y,const char *text,u32 color){ uiText(x,y+13,text,color,0.50f); }
static void drawTextLarge(int x,int y,const char *text,u32 color){ uiText(x,y+23,text,color,0.90f); }

#define COLOR_BG2      0xFF101419
#define COLOR_SURFACE  0xFF181D23
#define COLOR_SURFACE2 0xFF20262E
#define COLOR_LINE     0xFF343A43
#define COLOR_MUTED    0xFF9299A3
#define COLOR_TEXT2    0xFFF4F5F7
#define COLOR_RED_GLOW 0x500000FF
#define COLOR_RED_SOFT 0xB00000FF

static void drawRoundFill(int x,int y,int w,int h,int r,u32 color)
{
    int i,j;
    const int seg=8;
    const float pi=3.14159265f;
    drawRect(x+r,y,w-2*r,h,color);
    drawRect(x,y+r,r,h-2*r,color);
    drawRect(x+w-r,y+r,r,h-2*r,color);
    for(i=0;i<4;i++){
        float cx=(i==0||i==3)?(float)(x+r):(float)(x+w-r);
        float cy=(i==0||i==1)?(float)(y+r):(float)(y+h-r);
        float a0=(i==0)?pi:(i==1)?(pi*1.5f):(i==2)?0.0f:(pi*0.5f);
        Vertex *v=(Vertex*)sceGuGetMemory((seg+2)*sizeof(Vertex));
        v[0].color=color; v[0].x=(short)cx; v[0].y=(short)cy; v[0].z=0;
        for(j=0;j<=seg;j++){
            float a=a0+(pi*0.5f/(float)seg)*(float)j;
            v[j+1].color=color;
            v[j+1].x=(short)(cx+cosf(a)*(float)r);
            v[j+1].y=(short)(cy+sinf(a)*(float)r);
            v[j+1].z=0;
        }
        sceGuDrawArray(GU_TRIANGLE_FAN,GU_COLOR_8888|GU_VERTEX_16BIT|GU_TRANSFORM_2D,seg+2,NULL,v);
    }
}

static void drawRoundBorder(int x,int y,int w,int h,int r,int t,u32 color)
{
    drawRoundFill(x,y,w,h,r,color);
    drawRoundFill(x+t,y+t,w-2*t,h-2*t,r>t?r-t:1,COLOR_SURFACE);
}

static void drawPlayTriangle(int cx,int cy,int size,u32 color)
{
    Vertex *v=(Vertex*)sceGuGetMemory(3*sizeof(Vertex));
    v[0].color=color;v[0].x=cx-size/3;v[0].y=cy-size;v[0].z=0;
    v[1].color=color;v[1].x=cx-size/3;v[1].y=cy+size;v[1].z=0;
    v[2].color=color;v[2].x=cx+size;v[2].y=cy;v[2].z=0;
    sceGuDrawArray(GU_TRIANGLES,GU_COLOR_8888|GU_VERTEX_16BIT|GU_TRANSFORM_2D,3,NULL,v);
}

static void drawLogo(int x,int y)
{
    drawRoundFill(x,y,30,22,7,COLOR_RED);
    drawPlayTriangle(x+16,y+11,5,COLOR_WHITE);
    drawText(x+40,y+1,"YouTube",COLOR_TEXT2);
}

static void drawSearchGlyph(int cx,int cy,u32 color)
{
    int i;
    for(i=0;i<10;i++){
        float a=(float)i*6.2831853f/10.0f;
        drawRect(cx+(int)(cosf(a)*7.0f),cy+(int)(sinf(a)*7.0f),2,2,color);
    }
    drawRect(cx+6,cy+6,8,2,color);
}

static void drawSidebarGlyph(int x,int y,int type,u32 color)
{
    if(type==0){drawRoundFill(x,y+2,18,14,4,color);drawPlayTriangle(x+9,y+9,4,COLOR_SURFACE);}
    else if(type==1){drawRect(x+2,y+2,14,2,color);drawRect(x+2,y+7,14,2,color);drawRect(x+2,y+12,14,2,color);}
    else if(type==2){drawRoundFill(x+2,y+3,4,14,2,color);drawRoundFill(x+9,y+7,4,10,2,color);drawRoundFill(x+16,y,4,17,2,color);}
    else if(type==3){drawRoundFill(x+2,y+2,18,14,3,color);drawRect(x+7,y+6,8,2,COLOR_SURFACE);drawRect(x+7,y+10,8,2,COLOR_SURFACE);}
    else {drawRoundFill(x+2,y+2,18,14,3,color);drawRect(x+5,y+6,12,2,COLOR_SURFACE);drawRect(x+5,y+10,12,2,COLOR_SURFACE);}
}

static void drawMedia(int x,int y,int w,int h,int index)
{
    int idx=index%VIDEO_COUNT;
    int sx=(idx%2)*MEDIA_CELL_W, sy=(idx/2)*MEDIA_CELL_H;
    TexVertex *v=(TexVertex*)sceGuGetMemory(2*sizeof(TexVertex));
    sceGuEnable(GU_TEXTURE_2D); sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,GU_ONE_MINUS_SRC_ALPHA,0,0);
    sceGuTexMode(GU_PSM_8888,0,0,0);
    sceGuTexImage(0,MEDIA_ATLAS_W,MEDIA_ATLAS_H,MEDIA_ATLAS_W,mediaAtlas);
    sceGuTexFunc(GU_TFX_REPLACE,GU_TCC_RGBA); sceGuTexFilter(GU_LINEAR,GU_LINEAR);
    v[0].u=sx;v[0].v=sy;v[0].color=COLOR_WHITE;v[0].x=x;v[0].y=y;v[0].z=0;
    v[1].u=sx+240;v[1].v=sy+80;v[1].color=COLOR_WHITE;v[1].x=x+w;v[1].y=y+h;v[1].z=0;
    sceGuDrawArray(GU_SPRITES,GU_TEXTURE_32BIT|GU_COLOR_8888|GU_VERTEX_16BIT|GU_TRANSFORM_2D,2,NULL,v);
    sceGuDisable(GU_TEXTURE_2D);
}

static void drawVideoCardModern(int index,int x,int y,int w,int h,int selected)
{
    int imageH=h-37;
    if(selected){drawRoundFill(x-3,y-3,w+6,h+6,12,COLOR_RED_GLOW);drawRoundFill(x-1,y-1,w+2,h+2,11,COLOR_RED_SOFT);}
    drawRoundFill(x,y,w,h,10,COLOR_SURFACE);
    drawMedia(x+2,y+2,w-4,imageH,index);
    drawRoundFill(x+w-44,y+imageH-20,38,17,5,0xD0000000);
    drawTextSmall(x+w-37,y+imageH-19,videos[index].duration,COLOR_WHITE);
    drawText(x+10,y+imageH+1,videos[index].title1,COLOR_TEXT2);
    drawTextSmall(x+10,y+imageH+20,videos[index].channel,COLOR_MUTED);
    if(selected)drawRoundFill(x+10,y+h-3,w-20,2,1,COLOR_RED);
}

