{
    const char *title="HOME";
    if(page==PAGE_TRENDING)title="TRENDING"; else if(page==PAGE_SHORTS)title="SHORTS"; else if(page==PAGE_SEARCH)title="SEARCH"; else if(page==PAGE_SETTINGS)title="SETTINGS"; else if(page==PAGE_LIBRARY)title="LIBRARY"; else if(page==PAGE_VIDEO)title="VIDEO";
    drawRect(0,0,480,50,COLOR_HEADER);
    drawLogo(15,13);
    drawTextSmall(116,18,title,COLOR_MUTED);
    drawSearchGlyph(419,24,COLOR_TEXT2);
    drawRoundFill(445,12,23,24,7,COLOR_SURFACE2);
    drawTextSmall(452,17,"R",COLOR_TEXT2);
    drawRect(0,49,480,1,COLOR_LINE);
}

static void drawHomeLike(int selected,int trending,int sidebarPos)
{
    const int *order=trending?trendOrder:homeOrder;
    int shift=sidebarPos+SIDEBAR_WIDTH;
    if(shift<0)shift=0;if(shift>SIDEBAR_WIDTH)shift=SIDEBAR_WIDTH;
    int left=14+shift,gap=10,right=12,avail=SCREEN_WIDTH-left-right;
    int cardW=(avail-gap)/2,cardH=91;
    drawRect(0,0,480,272,COLOR_BG);
    drawHeaderModern(trending?PAGE_TRENDING:PAGE_HOME);
    drawTextSmall(left,55,trending?"TRENDING NOW":"RECOMMENDED FOR YOU",COLOR_MUTED);
    drawVideoCardModern(order[0],left,70,cardW,cardH,selected==order[0]);
    drawVideoCardModern(order[1],left+cardW+gap,70,cardW,cardH,selected==order[1]);
    drawVideoCardModern(order[2],left,170,cardW,cardH,selected==order[2]);
    drawVideoCardModern(order[3],left+cardW+gap,170,cardW,cardH,selected==order[3]);
}

