static void audioInit(void){if(uiSounds)audioChannel=sceAudioChReserve(-1,1024,PSP_AUDIO_FORMAT_MONO);}
static void audioTerm(void){if(audioChannel>=0){sceAudioChRelease(audioChannel);audioChannel=-1;}}
static void playTone(int type){int i,period,amp;if(!uiSounds||audioChannel<0)return;period=type==0?96:72;amp=type==0?350:500;for(i=0;i<1024;i++)audioBuffer[i]=((i%period)<period/2)?amp:-amp;sceAudioOutputBlocking(audioChannel,PSP_AUDIO_VOLUME_MAX/8,audioBuffer);}
static int sidebarPage(int s){return s==0?PAGE_HOME:s==1?PAGE_TRENDING:s==2?PAGE_SHORTS:s==3?PAGE_SETTINGS:PAGE_LIBRARY;}
static int pageSidebarIndex(int p){return p==PAGE_TRENDING?1:p==PAGE_SHORTS?2:p==PAGE_SETTINGS?3:p==PAGE_LIBRARY?4:0;}

int main(void)
{
    SceCtrlData pad;unsigned int oldButtons=0;int page=PAGE_HOME,selectedVideo=0,selectedSetting=0,selectedShort=0;int sidebarOpen=0,sidebarSelected=0;int sidebarX=-SIDEBAR_WIDTH,sidebarTarget=-SIDEBAR_WIDTH;
    SetupCallbacks();initGraphics();uiFontInit();audioInit();sceCtrlSetSamplingCycle(0);sceCtrlSetSamplingMode(PSP_CTRL_MODE_DIGITAL);
    while(running){unsigned int pressed;sceCtrlReadBufferPositive(&pad,1);pressed=pad.Buttons&~oldButtons;oldButtons=pad.Buttons;
        if(pressed&PSP_CTRL_LTRIGGER){sidebarOpen=!sidebarOpen;sidebarSelected=pageSidebarIndex(page);sidebarTarget=sidebarOpen?0:-SIDEBAR_WIDTH;playTone(0);}
        if(sidebarOpen){if(pressed&PSP_CTRL_UP){sidebarSelected=(sidebarSelected+4)%5;playTone(0);}if(pressed&PSP_CTRL_DOWN){sidebarSelected=(sidebarSelected+1)%5;playTone(0);}if(pressed&PSP_CTRL_CROSS){page=sidebarPage(sidebarSelected);sidebarOpen=0;sidebarTarget=-SIDEBAR_WIDTH;playTone(1);}if(pressed&PSP_CTRL_CIRCLE){sidebarOpen=0;sidebarTarget=-SIDEBAR_WIDTH;playTone(0);}}
        else {if(page==PAGE_HOME||page==PAGE_TRENDING){const int *o=page==PAGE_HOME?homeOrder:trendOrder;int pos=0,i;for(i=0;i<4;i++)if(o[i]==selectedVideo)pos=i;if(pressed&PSP_CTRL_LEFT&&pos%2)selectedVideo=o[pos-1];if(pressed&PSP_CTRL_RIGHT&&pos%2==0)selectedVideo=o[pos+1];if(pressed&PSP_CTRL_UP&&pos>=2)selectedVideo=o[pos-2];if(pressed&PSP_CTRL_DOWN&&pos<2)selectedVideo=o[pos+2];if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT|PSP_CTRL_UP|PSP_CTRL_DOWN))playTone(0);if(pressed&PSP_CTRL_CROSS){page=PAGE_VIDEO;playTone(1);}}
        else if(page==PAGE_SHORTS){if(pressed&PSP_CTRL_LEFT&&selectedShort>0)selectedShort--;if(pressed&PSP_CTRL_RIGHT&&selectedShort<2)selectedShort++;if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT))playTone(0);if(pressed&PSP_CTRL_CROSS){selectedVideo=selectedShort;page=PAGE_VIDEO;playTone(1);}}
        else if(page==PAGE_SETTINGS){if(pressed&PSP_CTRL_UP)selectedSetting=(selectedSetting+3)%4;if(pressed&PSP_CTRL_DOWN)selectedSetting=(selectedSetting+1)%4;if(pressed&(PSP_CTRL_UP|PSP_CTRL_DOWN))playTone(0);if(selectedSetting==3&&(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT|PSP_CTRL_CROSS))){uiSounds=!uiSounds;if(uiSounds&&audioChannel<0)audioChannel=sceAudioChReserve(-1,1024,PSP_AUDIO_FORMAT_MONO);playTone(1);}}
        else if(page==PAGE_SEARCH){if(pressed&PSP_CTRL_CROSS)playTone(1);}else if(page==PAGE_VIDEO){if(pressed&PSP_CTRL_CROSS)playTone(1);}if(pressed&PSP_CTRL_RTRIGGER){page=PAGE_SEARCH;playTone(1);}if(pressed&PSP_CTRL_CIRCLE){page=PAGE_HOME;playTone(0);}}
        if(sidebarX<sidebarTarget){sidebarX+=10;if(sidebarX>sidebarTarget)sidebarX=sidebarTarget;}else if(sidebarX>sidebarTarget){sidebarX-=10;if(sidebarX<sidebarTarget)sidebarX=sidebarTarget;}
        sceGuStart(GU_DIRECT,list);sceGuClearColor(COLOR_BG);sceGuClear(GU_COLOR_BUFFER_BIT|GU_DEPTH_BUFFER_BIT);
        if(page==PAGE_HOME)drawHomeLike(selectedVideo,0,sidebarX);else if(page==PAGE_TRENDING)drawHomeLike(selectedVideo,1,sidebarX);else if(page==PAGE_SHORTS)drawShorts(selectedShort);else if(page==PAGE_SEARCH)drawSearch(1);else if(page==PAGE_SETTINGS)drawSettings(selectedSetting,uiSounds);else if(page==PAGE_LIBRARY)drawLibrary();else drawVideoDetails(selectedVideo);
        drawSidebar(sidebarX,sidebarSelected);sceGuFinish();sceGuSync(0,0);sceDisplayWaitVblankStart();sceGuSwapBuffers();sceKernelDelayThread(1000);
    }
    audioTerm();uiFontTerm();sceGuTerm();sceKernelExitGame();return 0;
}
